<?php session_start(); require_once __DIR__.'/../app/config/config.php'; if(!empty($_SESSION['user'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST' && $pdo){$stmt=$pdo->prepare('SELECT u.*,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.password_hash=SHA2(?,256) AND u.active=1');$stmt->execute([trim($_POST['email']),$_POST['password']]);$user=$stmt->fetch();if($user){$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']];header('Location: index.php');exit;} $error='Email atau password salah.';} ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · EduInsight AI</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="login-page"><div class="login-card"><div class="brand centered"><span class="brand-mark">E</span><div><strong>EduInsight</strong><small>AI Learning Analytics</small></div></div><h1>Masuk ke sistem</h1><p class="muted">Kelola pembelajaran berbasis data.</p><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><label>Email<input type="email" name="email" value="guru@eduinsight.local" required></label><label>Password<input type="password" name="password" value="guru123" required></label><button class="btn primary full" type="submit">Masuk</button></form><div class="demo-login"><b>Akun demo</b><br>Guru: guru@eduinsight.local / guru123<br>Admin: admin@eduinsight.local / admin123</div></div></body></html>
